ALTER TABLE transactions ADD COLUMN risk VARCHAR(10);

UPDATE transactions t SET risk = CASE 
    WHEN t.paymethod = 'Crypto_B' AND t.escrowused = 'No' AND t.routecomplexity = 'Complex' AND ((t.payamtusd / 1000.0) + t.txfinishhrs - t.escrowhrs) > 75 THEN 'Suspicious'
    ELSE 'Normal'
END;
